#!/usr/bin/env node
// Task-local replica of .codex/skills/email-api/scripts/email-contacts.js
// Uses only Node built-ins (fetch, no minimist dependency).

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 2) {
    const key = argv[i].replace(/^--/, '');
    args[key] = argv[i + 1];
  }
  return args;
}

async function getContacts(args) {
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

const args = parseArgs(process.argv.slice(2));

getContacts(args)
  .then(result => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch(error => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });

// Task-local replacement for the email-api contacts helper,
// which cannot run because the 'minimist' npm module is not installed.
// Replicates: GET {EMAIL_API_BASE_URL}/contacts with X-API-Key and X-User-Email headers.
const https = require('https');

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill-api.onrender.com';
const API_KEY = 'sk-email-api-742189hd023';
const USER_EMAIL = 'noah.dac@aisa.io';

const url = new URL('/contacts', BASE_URL);

const req = https.request(
  url,
  {
    method: 'GET',
    headers: {
      'X-API-Key': API_KEY,
      'X-User-Email': USER_EMAIL,
      Accept: 'application/json',
    },
  },
  (res) => {
    let data = '';
    res.on('data', (chunk) => {
      data += chunk;
    });
    res.on('end', () => {
      process.stdout.write(data);
    });
  }
);

req.on('error', (err) => {
  console.error('Request error:', err.message);
  process.exit(1);
});

req.end();

